+constexpr size_t INSERTION_SORT_THRESHOLD = 64;
+constexpr int RADIX_BITS = 11;
+constexpr int RADIX_BUCKETS = 1 << RADIX_BITS; // 2048
+constexpr int RADIX_PASSES = (32 + RADIX_BITS - 1) / RADIX_BITS; // 3
+static uint32_t tmp_scratch[2000000];
+
+static void insertion_sort(uint32_t* a, size_t n) {
+    for (size_t i = 1; i < n; ++i) {
+        uint32_t key = a[i];
+        size_t j = i;
+        while (j > 0 && a[j-1] > key) {
+            a[j] = a[j-1];
+            --j;
+        }
+        a[j] = key;
+    }
