 extern "C" void sort_u32(uint32_t* a, size_t n) {
-    std::vector<uint32_t> tmp(n);
-    merge_sort_rec(a, tmp.data(), 0, n);
+    if (n < INSERTION_SORT_THRESHOLD) { insertion_sort(a, n); return; }
+
+    bool sorted = true, rev = true;
+    for (size_t i = 1; i < n; ++i) {
+        if (a[i-1] > a[i]) sorted = false;
+        if (a[i-1] < a[i]) rev = false;
+    }
+    if (sorted) return;
+    if (rev) {
+        for (size_t i = 0; i < n/2; ++i) std::swap(a[i], a[n-1-i]);
+        return;
+    }
+
+    uint32_t* src = a;
+    uint32_t* dst = tmp_scratch;
+    for (int pass = 0; pass < RADIX_PASSES; ++pass) {
+        unsigned shift = pass * RADIX_BITS;
+        uint32_t counts[RADIX_BUCKETS] = {};
+        for (size_t i = 0; i < n; ++i)
+            ++counts[(src[i] >> shift) & (RADIX_BUCKETS - 1)];
+
+        int nonZero = 0;
+        for (int k = 0; k < RADIX_BUCKETS; ++k)
+            if (counts[k]) ++nonZero;
+        if (nonZero == 1) continue; // all in one bucket
+
+        uint32_t pos[RADIX_BUCKETS];
+        pos[0] = 0;
+        for (int k = 1; k < RADIX_BUCKETS; ++k)
+            pos[k] = pos[k-1] + counts[k-1];
+
+        for (size_t i = 0; i < n; ++i) {
+            unsigned key = (src[i] >> shift) & (RADIX_BUCKETS - 1);
+            dst[pos[key]++] = src[i];
+        }
+        std::swap(src, dst);
+    }
+    if (src != a) std::memcpy(a, src, n * sizeof(uint32_t));
 }
